let proceduralIceSimulationShader;

let fullScreenQuadVertexGeometryCode = `
attribute vec3 aPosition;
varying vec2 vNormalizedDeviceCoordinates;

void main() {
  vNormalizedDeviceCoordinates = aPosition.xy;
  gl_Position = vec4(aPosition, 1.0);
}
`;

let optimizedAnalyticalRaycastFragmentCode = `
precision highp float;

varying vec2 vNormalizedDeviceCoordinates;

uniform vec2 uCanvasResolution;
uniform float uElapsedTime;

vec2 calculatePseudoRandomHash(vec2 gridInputCoordinate) {
    gridInputCoordinate = vec2(dot(gridInputCoordinate, vec2(127.1, 311.7)), dot(gridInputCoordinate, vec2(269.5, 183.3)));
    return fract(sin(gridInputCoordinate) * 43758.5453123);
}

float computeSmoothValueNoise(vec2 spatialCoordinate) {
    vec2 integerComponent = floor(spatialCoordinate);
    vec2 fractionalComponent = fract(spatialCoordinate);
    vec2 cubicSmoothing = fractionalComponent * fractionalComponent * (3.0 - 2.0 * fractionalComponent);

    float bottomEdgeInterpolation = mix(fract(sin(dot(integerComponent + vec2(0.0, 0.0), vec2(12.9898, 78.233))) * 43758.5453123),
                                        fract(sin(dot(integerComponent + vec2(1.0, 0.0), vec2(12.9898, 78.233))) * 43758.5453123), cubicSmoothing.x);
    float topEdgeInterpolation = mix(fract(sin(dot(integerComponent + vec2(0.0, 1.0), vec2(12.9898, 78.233))) * 43758.5453123),
                                     fract(sin(dot(integerComponent + vec2(1.0, 1.0), vec2(12.9898, 78.233))) * 43758.5453123), cubicSmoothing.x);

    return mix(bottomEdgeInterpolation, topEdgeInterpolation, cubicSmoothing.y);
}

float computeFractalBrownianMotion(vec2 spatialCoordinate) {
    float accumulatedNoiseValue = 0.0;
    float currentAmplitudeMultiplier = 0.5;
    vec2 shiftedCoordinatePosition = spatialCoordinate;
    mat2 arbitraryRotationMatrix = mat2(0.8, -0.6, 0.6, 0.8);

    for(int octaveIterator = 0; octaveIterator < 4; octaveIterator++) {
        accumulatedNoiseValue += currentAmplitudeMultiplier * computeSmoothValueNoise(shiftedCoordinatePosition);
        shiftedCoordinatePosition = arbitraryRotationMatrix * shiftedCoordinatePosition * 2.0;
        currentAmplitudeMultiplier *= 0.5;
    }
    return accumulatedNoiseValue;
}

float calculateVoronoiDistanceToEdge(vec2 spatialCoordinate) {
    vec2 integerGridSector = floor(spatialCoordinate);
    vec2 fractionalGridSector = fract(spatialCoordinate);

    vec2 closestCellGridOffset;
    vec2 closestCellRelativePositionVector;
    float minimumSquaredDistanceMetric = 8.0;

    for (int verticalNeighborIterator = -1; verticalNeighborIterator <= 1; verticalNeighborIterator++) {
        for (int horizontalNeighborIterator = -1; horizontalNeighborIterator <= 1; horizontalNeighborIterator++) {
            vec2 neighborGridSectorOffset = vec2(float(horizontalNeighborIterator), float(verticalNeighborIterator));
            vec2 randomCellCorePoint = calculatePseudoRandomHash(integerGridSector + neighborGridSectorOffset);
            vec2 relativeDistanceVectorToCore = neighborGridSectorOffset + randomCellCorePoint - fractionalGridSector;
            float currentCalculatedSquaredDistance = dot(relativeDistanceVectorToCore, relativeDistanceVectorToCore);

            if (currentCalculatedSquaredDistance < minimumSquaredDistanceMetric) {
                minimumSquaredDistanceMetric = currentCalculatedSquaredDistance;
                closestCellRelativePositionVector = relativeDistanceVectorToCore;
                closestCellGridOffset = neighborGridSectorOffset;
            }
        }
    }

    float minimumEdgeBoundaryDistance = 8.0;
    for (int secondaryVerticalNeighborIterator = -2; secondaryVerticalNeighborIterator <= 2; secondaryVerticalNeighborIterator++) {
        for (int secondaryHorizontalNeighborIterator = -2; secondaryHorizontalNeighborIterator <= 2; secondaryHorizontalNeighborIterator++) {
            vec2 extendedNeighborGridSectorOffset = closestCellGridOffset + vec2(float(secondaryHorizontalNeighborIterator), float(secondaryVerticalNeighborIterator));
            vec2 extendedRandomCellCorePoint = calculatePseudoRandomHash(integerGridSector + extendedNeighborGridSectorOffset);
            vec2 extendedRelativeDistanceVectorToCore = extendedNeighborGridSectorOffset + extendedRandomCellCorePoint - fractionalGridSector;

            vec2 internalDifferenceVector = closestCellRelativePositionVector - extendedRelativeDistanceVectorToCore;
            if (dot(internalDifferenceVector, internalDifferenceVector) > 0.00001) {
                vec2 structuralMidPointVector = 0.5 * (closestCellRelativePositionVector + extendedRelativeDistanceVectorToCore);
                vec2 normalizedStructuralDifferenceVector = normalize(extendedRelativeDistanceVectorToCore - closestCellRelativePositionVector);
                minimumEdgeBoundaryDistance = min(minimumEdgeBoundaryDistance, dot(structuralMidPointVector, normalizedStructuralDifferenceVector));
            }
        }
    }
    return minimumEdgeBoundaryDistance;
}

vec3 evaluateSunriseAtmosphere(vec3 viewingDirectionVector) {
    vec3 warmSunriseHorizonColor = vec3(0.95, 0.45, 0.25);
    vec3 deepZenithSkyColor = vec3(0.15, 0.25, 0.55);
    float verticalGradientInterpolationFactor = clamp(viewingDirectionVector.y * 1.5 + 0.2, 0.0, 1.0);
    vec3 compositedAtmosphericSky = mix(warmSunriseHorizonColor, deepZenithSkyColor, verticalGradientInterpolationFactor);

    vec3 solarLightDirectionalVector = normalize(vec3(0.0, 0.08, 1.0));
    float solarDiscLuminanceIntensity = pow(max(dot(viewingDirectionVector, solarLightDirectionalVector), 0.0), 300.0);
    compositedAtmosphericSky += vec3(1.0, 0.9, 0.6) * solarDiscLuminanceIntensity * 2.5;

    float solarAuraGlowIntensity = pow(max(dot(viewingDirectionVector, solarLightDirectionalVector), 0.0), 15.0);
    compositedAtmosphericSky += vec3(1.0, 0.3, 0.0) * solarAuraGlowIntensity * 0.6;

    return compositedAtmosphericSky;
}

vec3 evaluateIridescentCoating(float geometricFresnelInputFactor) {
    vec3 spectralPaletteBaseOffset = vec3(0.5, 0.5, 0.5);
    vec3 spectralPaletteColorAmplitude = vec3(0.5, 0.5, 0.5);
    vec3 spectralPaletteOscillationFrequency = vec3(1.2, 1.0, 0.8);
    vec3 spectralPalettePhaseShift = vec3(0.0, 0.33, 0.67);
    return spectralPaletteBaseOffset + spectralPaletteColorAmplitude * cos(6.28318 * (spectralPaletteOscillationFrequency * geometricFresnelInputFactor + spectralPalettePhaseShift));
}

vec2 calculateIceSurfaceTopographyProperties(vec2 worldPlaneHorizontalCoordinate, float temporalEvolutionValue) {
    float dynamicGeologicalPhaseProgression = mod(temporalEvolutionValue * 0.3 + computeFractalBrownianMotion(worldPlaneHorizontalCoordinate * 0.1) * 1.5, 12.0);

    float crystallineFreezingBlendFactor = smoothstep(1.0, 4.0, dynamicGeologicalPhaseProgression) - smoothstep(9.0, 11.0, dynamicGeologicalPhaseProgression);
    float structuralCrackingBlendFactor = smoothstep(5.0, 6.5, dynamicGeologicalPhaseProgression) - smoothstep(8.0, 10.0, dynamicGeologicalPhaseProgression);

    vec2 liquidFlowDisplacementVector = vec2(temporalEvolutionValue * 0.4, temporalEvolutionValue * 0.2);
    float liquidWaveVerticalHeight = computeFractalBrownianMotion(worldPlaneHorizontalCoordinate * 1.5 + liquidFlowDisplacementVector) * 0.06;

    float solidMicroStructureVerticalHeight = computeFractalBrownianMotion(worldPlaneHorizontalCoordinate * 4.0) * 0.02;

    float voronoiEdgeProximityDistance = calculateVoronoiDistanceToEdge(worldPlaneHorizontalCoordinate * 1.2);
    float internalCrackVerticalDepth = smoothstep(0.06, 0.0, voronoiEdgeProximityDistance) * structuralCrackingBlendFactor * 0.15;

    float blendedSurfaceElevationHeight = mix(liquidWaveVerticalHeight, solidMicroStructureVerticalHeight - internalCrackVerticalDepth, crystallineFreezingBlendFactor);
    float aggregateIceStateConditionFactor = crystallineFreezingBlendFactor + structuralCrackingBlendFactor * 0.5;

    return vec2(blendedSurfaceElevationHeight, aggregateIceStateConditionFactor);
}

vec3 deriveSurfaceNormalVector(vec2 worldPlaneHorizontalCoordinate, float temporalEvolutionValue) {
    float finiteDifferenceEpsilonValue = 0.01;
    float centerElevationHeight = calculateIceSurfaceTopographyProperties(worldPlaneHorizontalCoordinate, temporalEvolutionValue).x;
    float rightElevationHeight = calculateIceSurfaceTopographyProperties(worldPlaneHorizontalCoordinate + vec2(finiteDifferenceEpsilonValue, 0.0), temporalEvolutionValue).x;
    float forwardElevationHeight = calculateIceSurfaceTopographyProperties(worldPlaneHorizontalCoordinate + vec2(0.0, finiteDifferenceEpsilonValue), temporalEvolutionValue).x;

    return normalize(vec3(centerElevationHeight - rightElevationHeight, finiteDifferenceEpsilonValue, centerElevationHeight - forwardElevationHeight));
}

void main() {
    vec2 aspectRatioCorrectedCoordinate = vNormalizedDeviceCoordinates;
    aspectRatioCorrectedCoordinate.x *= uCanvasResolution.x / uCanvasResolution.y;

    vec3 activeCameraOriginPosition = vec3(0.0, 0.8, uElapsedTime * 0.8);
    vec3 activeCameraTargetPosition = activeCameraOriginPosition + vec3(0.0, -0.15, 1.0);

    vec3 cameraForwardAxisVector = normalize(activeCameraTargetPosition - activeCameraOriginPosition);
    vec3 cameraRightAxisVector = normalize(cross(cameraForwardAxisVector, vec3(0.0, 1.0, 0.0)));
    vec3 cameraUpAxisVector = cross(cameraRightAxisVector, cameraForwardAxisVector);

    vec3 primaryRayViewingDirection = normalize(aspectRatioCorrectedCoordinate.x * cameraRightAxisVector + aspectRatioCorrectedCoordinate.y * cameraUpAxisVector + 1.2 * cameraForwardAxisVector);

    float mathematicalPlaneIntersectionDistanceValue = -activeCameraOriginPosition.y / primaryRayViewingDirection.y;

    vec3 finalCompositedPixelOutputColor;

    if (mathematicalPlaneIntersectionDistanceValue > 0.0) {
        vec3 intersectionWorldSpacePosition = activeCameraOriginPosition + primaryRayViewingDirection * mathematicalPlaneIntersectionDistanceValue;

        vec2 preliminarySurfaceDataReadout = calculateIceSurfaceTopographyProperties(intersectionWorldSpacePosition.xz, uElapsedTime);
        intersectionWorldSpacePosition += primaryRayViewingDirection * preliminarySurfaceDataReadout.x * 2.0;

        vec3 definitiveSurfaceNormalVector = deriveSurfaceNormalVector(intersectionWorldSpacePosition.xz, uElapsedTime);
        vec2 definitiveSurfaceDataReadout = calculateIceSurfaceTopographyProperties(intersectionWorldSpacePosition.xz, uElapsedTime);

        vec3 reflectionObservationVector = -primaryRayViewingDirection;
        float surfaceFresnelResponseFactor = pow(1.0 - max(dot(definitiveSurfaceNormalVector, reflectionObservationVector), 0.0), 4.0);

        vec3 atmosphericReflectionSampleColor = evaluateSunriseAtmosphere(reflect(primaryRayViewingDirection, definitiveSurfaceNormalVector));
        vec3 structuralIridescenceSampleColor = evaluateIridescentCoating(surfaceFresnelResponseFactor * 1.5 - definitiveSurfaceDataReadout.x * 8.0);

        vec3 abyssalWaterBaseSubsurfaceColor = vec3(0.02, 0.08, 0.15);
        vec3 crystallineIceBaseSubsurfaceColor = vec3(0.7, 0.85, 0.95) * structuralIridescenceSampleColor;

        vec3 interpolatedMaterialBaseSubsurfaceColor = mix(abyssalWaterBaseSubsurfaceColor, crystallineIceBaseSubsurfaceColor, clamp(definitiveSurfaceDataReadout.y, 0.0, 1.0));

        float subsurfaceCrackIlluminationIntensity = smoothstep(0.0, 0.1, -definitiveSurfaceDataReadout.x) * clamp(definitiveSurfaceDataReadout.y, 0.0, 1.0);
        interpolatedMaterialBaseSubsurfaceColor += vec3(0.1, 0.5, 0.9) * subsurfaceCrackIlluminationIntensity * 1.5;

        finalCompositedPixelOutputColor = mix(interpolatedMaterialBaseSubsurfaceColor, atmosphericReflectionSampleColor, surfaceFresnelResponseFactor + clamp(definitiveSurfaceDataReadout.y, 0.0, 1.0) * 0.2);

        vec3 solarIlluminationDirectionalVector = normalize(vec3(0.0, 0.08, 1.0));
        vec3 specularReflectionVector = reflect(primaryRayViewingDirection, definitiveSurfaceNormalVector);
        float surfaceRoughnessPowerCoefficient = mix(150.0, 40.0, clamp(definitiveSurfaceDataReadout.y, 0.0, 1.0));
        float specularHighlightIntensityCoefficient = pow(max(dot(specularReflectionVector, solarIlluminationDirectionalVector), 0.0), surfaceRoughnessPowerCoefficient);
        finalCompositedPixelOutputColor += vec3(1.0, 0.8, 0.5) * specularHighlightIntensityCoefficient * mix(1.5, 0.5, clamp(definitiveSurfaceDataReadout.y, 0.0, 1.0));

        float atmosphericDepthFogBlendingFactor = exp(-0.035 * mathematicalPlaneIntersectionDistanceValue);
        vec3 horizonAtmosphereSampleColor = evaluateSunriseAtmosphere(primaryRayViewingDirection);
        finalCompositedPixelOutputColor = mix(horizonAtmosphereSampleColor, finalCompositedPixelOutputColor, atmosphericDepthFogBlendingFactor);

    } else {
        finalCompositedPixelOutputColor = evaluateSunriseAtmosphere(primaryRayViewingDirection);
    }

    gl_FragColor = vec4(finalCompositedPixelOutputColor, 1.0);
}
`;

async function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL);
  pixelDensity(1);
  noStroke();
  proceduralIceSimulationShader = createShader(fullScreenQuadVertexGeometryCode, optimizedAnalyticalRaycastFragmentCode);
}

function draw() {
  shader(proceduralIceSimulationShader);
  proceduralIceSimulationShader.setUniform('uElapsedTime', millis() / 1000.0);
  proceduralIceSimulationShader.setUniform('uCanvasResolution', [width, height]);
  quad(-1, -1, 1, -1, 1, 1, -1, 1);
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}
